import React, { useState, useEffect } from 'react';
import { useParams, Link } from 'react-router-dom';
import { getLatestMovies } from '../api/tmdb';

function MovieDetail() {
  const { id } = useParams();
  const [movie, setMovie] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchMovieDetail = async () => {
      setLoading(true);
      const movies = await getLatestMovies();
      // URL의 id와 일치하는 영화를 찾음 (없을 경우 첫 번째 영화 지정)
      const foundMovie = movies.find((m) => String(m.id) === String(id)) || movies[0];
      setMovie(foundMovie);
      setLoading(false);
    };
    fetchMovieDetail();
  }, [id]);

  if (loading || !movie) {
    return (
      <div className="w-full min-h-screen bg-[#0b090e] flex items-center justify-center text-white">
        <p className="text-sm font-bold animate-pulse text-purple-400">영화 정보를 불러오는 중...</p>
      </div>
    );
  }

  // 이미지 경로 설정 (TMDB 기본 이미지 혹은 대체 이미지)
  const posterUrl = movie.poster_path 
    ? `https://image.tmdb.org/t/p/w500${movie.poster_path}` 
    : "https://via.placeholder.com/300x450?text=No+Image";

  const backdropUrl = movie.backdrop_path 
    ? `https://image.tmdb.org/t/p/original${movie.backdrop_path}` 
    : posterUrl;

  return (
    <div className="w-full min-h-screen bg-[#0b090e] text-white flex flex-col items-center pb-20">
      
      {/* 상단 히어로 백드롭 영역 */}
      <div 
        className="w-full relative h-[420px] flex flex-col justify-end p-8 bg-cover bg-center" 
        style={{ backgroundImage: `url(${backdropUrl})` }}
      >
        <div className="absolute inset-0 bg-gradient-to-t from-[#0b090e] via-[#0b090e]/60 to-black/40" />
        <div className="relative z-10 max-w-4xl w-full mx-auto space-y-2">
          <h1 className="text-3xl md:text-5xl font-black tracking-tight drop-shadow-lg">
            {movie.title || movie.name}
          </h1>
          <p className="text-xs text-zinc-300 font-bold tracking-wide">
            {movie.release_date ? movie.release_date.split('-')[0] : '2026'} | 13+ | 1h 51m | Language: {movie.original_language?.toUpperCase() || 'EN'}
          </p>
        </div>
      </div>

      {/* 중앙 본문 정보 영역 (포스터 깨짐 방지 및 정렬 보정) */}
      <div className="max-w-4xl w-full px-6 -mt-8 relative z-20 grid grid-cols-1 md:grid-cols-3 gap-8 items-start">
        
        {/* 포스터 박스 */}
        <div className="w-48 h-72 rounded-xl overflow-hidden shadow-2xl border border-white/10 mx-auto md:mx-0 bg-zinc-900 flex-shrink-0">
          <img src={posterUrl} alt={movie.title} className="w-full h-full object-cover" />
        </div>

        {/* 상세 설명 박스 */}
        <div className="md:col-span-2 space-y-4 bg-[#181124]/90 backdrop-blur-md p-6 rounded-2xl border border-purple-500/20 shadow-xl">
          <div>
            <span className="text-[11px] text-purple-400 font-bold uppercase tracking-wider">Overview</span>
            <p className="text-sm font-bold text-white mt-1">TMDB Official Release</p>
          </div>

          <p className="text-xs text-zinc-300 leading-relaxed">
            {movie.overview || "등록된 상세 줄거리 정보가 없습니다."}
          </p>

          <div className="flex gap-2 pt-2 flex-wrap">
            <span className="text-[10px] font-bold px-3 py-1 rounded-full border border-purple-400/40 text-purple-200 bg-purple-950/40">
              Drama
            </span>
            <span className="text-[10px] font-bold px-3 py-1 rounded-full border border-purple-400/40 text-purple-200 bg-purple-950/40">
              Cinema
            </span>
          </div>

          <div className="flex items-center justify-between pt-4 border-t border-white/10">
            <span className="text-xs font-bold text-zinc-400">Rating Score</span>
            <div className="w-12 h-12 rounded-full border-2 border-yellow-400 flex items-center justify-center text-yellow-400 font-black text-sm shadow-[0_0_10px_rgba(250,204,21,0.3)]">
              {movie.vote_average ? movie.vote_average.toFixed(1) : '8.5'}
            </div>
          </div>
        </div>

      </div>

      {/* 갤러리 영역 (깨짐 방지 object-cover 적용) */}
      <div className="max-w-4xl w-full px-6 mt-12">
        <h3 className="text-sm font-black tracking-widest text-purple-300 mb-4 uppercase">Gallery</h3>
        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
          <div className="h-36 rounded-xl overflow-hidden border border-white/10 shadow-lg bg-zinc-900">
            <img src={backdropUrl} alt="gallery 1" className="w-full h-full object-cover hover:scale-105 transition duration-500" />
          </div>
          <div className="h-36 rounded-xl overflow-hidden border border-white/10 shadow-lg bg-zinc-900">
            <img src={posterUrl} alt="gallery 2" className="w-full h-full object-cover hover:scale-105 transition duration-500" />
          </div>
          <div className="h-36 rounded-xl overflow-hidden border border-white/10 shadow-lg bg-zinc-900">
            <img src={backdropUrl} alt="gallery 3" className="w-full h-full object-cover hover:scale-105 transition duration-500" />
          </div>
        </div>
      </div>

    </div>
  );
}

export default MovieDetail;
